const frameMap = (refId) => {
  const f = context.panel.data.series.find((s) => s.refId === refId);
  if (!f) return {};
  const nf = f.fields.find((fl) => fl.name === 'node');
  const vf = f.fields.find((fl) => fl.name === 'Value #' + refId);
  const m = {};
  nf.values.forEach((n, i) => { m[n] = vf.values[i]; });
  return m;
};
const usageMap = frameMap('A'), capacityMap = frameMap('B'), requestMap = frameMap('C'), limitMap = frameMap('D');
const nodeSet = new Set([...Object.keys(usageMap), ...Object.keys(capacityMap), ...Object.keys(requestMap), ...Object.keys(limitMap)]);
const nodes = Array.from(nodeSet).sort();
const usage = nodes.map((n) => usageMap[n]);
const capacity = nodes.map((n) => capacityMap[n]);
const request = nodes.map((n) => requestMap[n]);
const limit = nodes.map((n) => limitMap[n]);
const fmt = (v) => (v == null ? '' : v.toFixed(2));

// AXIS_MAX > 100 on purpose: clipping request to 100 hid overcommit - a
// node at 104% of capacity requested looked identical to one exactly
// at 100%. Axis extends to 150%, a solid reference line is drawn at
// x=100, and a bar whose green segment crosses it visibly overshoots -
// the distance past the line IS the overcommit, no separate flag
// needed.
//
// No separate limit marker: once VPA manages a container it keeps
// request and limit equal (controlledValues: RequestsAndLimits), so a
// limit marker would just sit on top of the usage/request marks already
// shown - redundant, not information. Limit is still surfaced as plain
// text in the tooltip below for whatever hasn't converged yet.
const AXIS_MAX = 150;
const clip = (v) => Math.max(0, Math.min(AXIS_MAX, v));
const usagePct = usage.map((v,i) => capacity[i] ? clip(100*(v||0)/capacity[i]) : 0);
const reqPct = request.map((v,i) => capacity[i] ? clip(100*(v||0)/capacity[i]) : 0);
const bandLow = reqPct;
const bandHigh = reqPct.map((v) => AXIS_MAX - v);

return {
  animation: false, // otherwise every dashboard data refresh replays the draw-in animation on every element, including the reference line
  grid: { left: 150, right: 70, top: 10, bottom: 30 },
  xAxis: { type: 'value', min: 0, max: AXIS_MAX, axisLabel: { formatter: '{value}%' } },
  yAxis: { type: 'category', inverse: true, data: nodes, axisLabel: { fontSize: 15 } },
  tooltip: {
    trigger: 'axis', axisPointer: { type: 'shadow' },
    formatter: (params) => {
      const i = params[0].dataIndex;
      return nodes[i] + '<br/>Used: ' + fmt(usage[i]) + ' / ' + fmt(capacity[i]) + ' cores' +
             '<br/>Request: ' + fmt(request[i]) + '  Limit: ' + fmt(limit[i]);
    }
  },
  series: [
    { name: 'under request', type: 'bar', stack: 'bands', barWidth: '55%', silent: true, z: 1,
      itemStyle: { color: '#37872D' }, data: bandLow,
      markLine: { silent: true, animation: false, symbol: 'none', label: { show: false },
        lineStyle: { color: '#FFFFFF', width: 2, type: 'solid' }, data: [{ xAxis: 100 }] } },
    { name: 'over request', type: 'bar', stack: 'bands', barWidth: '55%', silent: true, z: 1,
      itemStyle: { color: '#C4162A' }, data: bandHigh },
    { name: 'Usage', type: 'scatter', symbol: 'rect', symbolSize: [4, 24], z: 4,
      itemStyle: { color: '#FFFFFF' },
      label: { show: true, position: 'right', fontSize: 13, color: '#FFFFFF',
        formatter: (p) => fmt(usage[p.dataIndex]) + ' / ' + fmt(capacity[p.dataIndex]) },
      data: usagePct.map((v,i) => [v, i]) }
  ]
};

